        <div>
          <div class="info-item"><span class="info-label">Matrícula Funcional:</span><span class="info-val" style="font-family: monospace;">${((ue=d.colaborador)==null?void 0:ue.matricula)||""}</span></div>
          <div class="info-item" style="margin-top: 4px;"><span class="info-label">Cargo Oficial:</span><span class="info-val">${((ye=d.colaborador)==null?void 0:ye.cargo)||""}</span></div>
          <div class="info-item" style="margin-top: 4px;"><span class="info-label">Departamento / Setor:</span><span class="info-val">${((Re=d.colaborador)==null?void 0:Re.departamento)||""}</span></div>
        </div>
